{
	int total = 0, bad = 0;

	bad += check_errors(&total);
	bad += check_dec(DEC4_CASES, (int)(sizeof(DEC4_CASES) / sizeof(DEC4_CASES[0])), &total);
	bad += check_rel("quad_solve", QUAD_SOLVE, (int)(sizeof(QUAD_SOLVE) / sizeof(QUAD_SOLVE[0])), 3, &total);
	bad += check_rel("deriv_poly3", DERIV_POLY3, (int)(sizeof(DERIV_POLY3) / sizeof(DERIV_POLY3[0])), 5, &total);
	bad += check_rel("integr_poly3", INTEGR_POLY3, (int)(sizeof(INTEGR_POLY3) / sizeof(INTEGR_POLY3[0])), 6, &total);
	bad += check_rel("linear2", LINEAR2, (int)(sizeof(LINEAR2) / sizeof(LINEAR2[0])), 6, &total);
	bad += check_rel("exp_solve", EXP_SOLVE, (int)(sizeof(EXP_SOLVE) / sizeof(EXP_SOLVE[0])), 2, &total);
	bad += check_rel("kinematic_v", KINEMATIC_V, (int)(sizeof(KINEMATIC_V) / sizeof(KINEMATIC_V[0])), 3, &total);
	bad += check_rel("proj_range", PROJ_RANGE, (int)(sizeof(PROJ_RANGE) / sizeof(PROJ_RANGE[0])), 3, &total);
	bad += check_rel("ohm_i", OHM_I, (int)(sizeof(OHM_I) / sizeof(OHM_I[0])), 2, &total);
	bad += check_rel("moles", MOLES, (int)(sizeof(MOLES) / sizeof(MOLES[0])), 2, &total);
	bad += check_rel("dilution", DILUTION, (int)(sizeof(DILUTION) / sizeof(DILUTION[0])), 3, &total);
	bad += check_rel("gas_p", GAS_P, (int)(sizeof(GAS_P) / sizeof(GAS_P[0])), 3, &total);
	printf("TOTAL: %d assertions, %d mismatches -> %s\n", total, bad,
	       bad == 0 ? "PASS" : "FAIL");
	return bad == 0 ? 0 : 1;
}
